from pathlib import Path

app=Path('src/App.jsx')
s=app.read_text(encoding='utf-8')

# PetNews: do not hide every article just because an image is missing.
s=s.replace('const items=(data.items||[]).filter(x=>x.image&&(category==="전체"||x.category===category)&&(!q||[x.title,x.description,x.source,x.category].some(v=>clean(v).toLowerCase().includes(q))));','const items=(data.items||[]).filter(x=>(category==="전체"||x.category===category)&&(!q||[x.title,x.description,x.source,x.category].some(v=>clean(v).toLowerCase().includes(q))));')

# PetMusic: keep list cache across remounts during one browser session.
s=s.replace('const musicCacheRef=useRef(new Map());','const musicCacheRef=useRef(window.__petgrowMusicCache||(window.__petgrowMusicCache=new Map()));')

# Guide/desktop map visual polish inside the existing CSS template, before Nearby section.
anchor='  /* ===== 내 주변 Pet ===== */'
css='''  /* ===== 2026-08-17 guide readability + map visibility polish ===== */\n  .info-guide-v4{max-width:980px!important;margin:0 auto!important;padding-bottom:44px!important}\n  .info-guide-search-card{padding:24px 26px!important;border-radius:22px!important;background:linear-gradient(135deg,#f4faf5,#fff)!important;border:1px solid #dfeadf!important;box-shadow:0 10px 30px rgba(48,78,56,.06)!important}\n  .info-guide-search-card h2{font-size:22px!important;letter-spacing:-.035em!important;margin:5px 0 6px!important}.info-guide-kicker{font-size:10px!important;letter-spacing:.14em!important;color:#4f8a5b!important;font-weight:900!important}\n  .info-guide-search-row{display:grid!important;grid-template-columns:auto minmax(0,1fr) auto!important;gap:9px!important;align-items:center!important;margin-top:15px!important;padding:7px 9px!important;border:1px solid #e0e9e2!important;border-radius:15px!important;background:#fff!important}.info-guide-search-row>span{font-size:15px!important}.info-guide-search-row .bg-input{border:0!important;box-shadow:none!important;padding:9px 4px!important;background:transparent!important}\n  .info-guide-section-head{display:flex!important;align-items:flex-end!important;justify-content:space-between!important;gap:12px!important;margin:24px 2px 11px!important}.info-guide-section-head h3{font-size:17px!important;margin:0!important}.info-guide-section-head small{font-size:11px!important;color:var(--sub)!important}\n  .info-guide-popular-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:10px!important}.info-guide-popular-btn{min-height:118px!important;padding:16px!important;border-radius:18px!important;text-align:left!important;display:flex!important;flex-direction:column!important;align-items:flex-start!important;gap:6px!important}.info-guide-popular-btn>span{font-size:23px!important}.info-guide-popular-btn>b{font-size:14px!important}.info-guide-popular-btn>small{font-size:11px!important;line-height:1.5!important;color:var(--sub)!important}\n  .info-guide-accordion-list{display:grid!important;gap:9px!important}.info-guide-accordion{border-radius:17px!important;overflow:hidden!important;padding:0!important}.info-guide-accordion-head{width:100%!important;display:grid!important;grid-template-columns:40px minmax(0,1fr) 28px!important;align-items:center!important;gap:10px!important;padding:15px 17px!important;border:0!important;background:#fff!important;text-align:left!important}.info-guide-accordion-head>span{width:38px!important;height:38px!important;border-radius:12px!important;display:grid!important;place-items:center!important;background:#eff6f0!important;font-size:19px!important}.info-guide-accordion-head b{font-size:14px!important}.info-guide-accordion-head small{display:block!important;margin-top:3px!important;font-size:11px!important;color:var(--sub)!important}.info-guide-accordion-head em{font-style:normal!important;font-size:20px!important;color:#63806a!important;text-align:center!important}.info-guide-accordion-body{padding:3px 18px 18px 68px!important;border-top:1px solid #edf1ee!important}.info-guide-accordion-body ol{margin:14px 0!important;padding:0!important;list-style:none!important;display:grid!important;gap:9px!important}.info-guide-accordion-body li{display:grid!important;grid-template-columns:24px 1fr!important;gap:9px!important;align-items:start!important}.info-guide-accordion-body li>span{width:22px!important;height:22px!important;border-radius:8px!important;background:#e9f3eb!important;color:#41724c!important;display:grid!important;place-items:center!important;font-size:10px!important;font-weight:900!important}.info-guide-accordion-body li p{margin:1px 0 0!important;font-size:12.5px!important;line-height:1.65!important}.info-guide-tip{padding:11px 13px!important;border-radius:12px!important;background:#f7faf7!important;font-size:11.5px!important;line-height:1.55!important}.info-guide-go{margin-top:12px!important}\n  .nearby-map-card,.nearby-map{display:block!important;visibility:visible!important}.nearby-map{min-height:430px!important}\n  @media(max-width:700px){.info-guide-v4{padding-left:12px!important;padding-right:12px!important}.info-guide-search-card{padding:18px!important}.info-guide-popular-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}.info-guide-popular-btn{min-height:105px!important;padding:13px!important}.info-guide-section-head{align-items:flex-start!important;flex-direction:column!important;gap:3px!important}.info-guide-accordion-body{padding-left:16px!important}.info-guide-search-row{grid-template-columns:auto minmax(0,1fr)!important}.info-guide-search-row .bg-chip{grid-column:1/-1!important;width:100%!important}.nearby-map{min-height:380px!important}}\n\n'''
if 'guide readability + map visibility polish' not in s and anchor in s:
    s=s.replace(anchor,css+anchor,1)
app.write_text(s,encoding='utf-8')

# Vercel Blob-less cover replacement fallback.
music=Path('api/music.js')
m=music.read_text(encoding='utf-8')
old='if(body.coverDataUrl){const f=parseDataUrl(body.coverDataUrl,IMAGE_MIME,MAX_COVER_BYTES);const ext=f.mime.includes("png")?"png":f.mime.includes("webp")?"webp":"jpg";const b=await put(`petmusic/covers/${id}-${Date.now()}.${ext}`,f.buffer,{access:"public",contentType:f.mime,token:process.env.BLOB_READ_WRITE_TOKEN});coverUrl=b.url;}'
new='if(body.coverDataUrl){const f=parseDataUrl(body.coverDataUrl,IMAGE_MIME,MAX_COVER_BYTES);if(process.env.BLOB_READ_WRITE_TOKEN){const ext=f.mime.includes("png")?"png":f.mime.includes("webp")?"webp":"jpg";const b=await put(`petmusic/covers/${id}-${Date.now()}.${ext}`,f.buffer,{access:"public",contentType:f.mime,token:process.env.BLOB_READ_WRITE_TOKEN});coverUrl=b.url;}else{coverUrl=String(body.coverDataUrl);}}'
m=m.replace(old,new)
# Avoid repeated starter DB work inside one warm server instance.
if 'let starterTracksReadyPromise' not in m:
    m=m.replace('async function ensureStarterTracks(){','let starterTracksReadyPromise=null;\nasync function ensureStarterTracks(){',1)
    m=m.replace('  const seedKey="petmusic-starter-thirtytwo-v4";','  if(starterTracksReadyPromise) return starterTracksReadyPromise;\n  starterTracksReadyPromise=(async()=>{\n  const seedKey="petmusic-starter-thirtytwo-v4";',1)
    # close wrapper at function end just before handler export area by targeting final meta insert marker if present
    marker='  await sql`insert into pg_app_meta(key,value) values(${seedKey},\'done\') on conflict(key) do update set value=excluded.value`;\n}'
    if marker in m:
        m=m.replace(marker,'  await sql`insert into pg_app_meta(key,value) values(${seedKey},\'done\') on conflict(key) do update set value=excluded.value`;\n  })().catch(e=>{starterTracksReadyPromise=null;throw e});\n  return starterTracksReadyPromise;\n}',1)
music.write_text(m,encoding='utf-8')

# Tarot timing + premium motion/result design.
tar=Path('src/PetDailyWidgets.jsx')
t=tar.read_text(encoding='utf-8')
t=t.replace('window.setTimeout(()=>setPhase("choose"),820)','window.setTimeout(()=>setPhase("choose"),720)')
t=t.replace('setPhase("reveal");window.setTimeout(()=>setPhase("result"),900)},650)','setPhase("reveal");window.setTimeout(()=>setPhase("result"),1150)},360)')
t=t.replace('"--r":`${(i-10.5)*2.25}deg`,"--lift":`${Math.abs(i-10.5)*1.1}px`,"--delay":`${i*22}ms`','"--r":`${(i-10.5)*1.7}deg`,"--lift":`${Math.abs(i-10.5)*0.72}px`,"--delay":`${i*16}ms`')
marker='/* PET_TAROT_MOTION_V5 */'
premium='''/* PET_TAROT_PREMIUM_V6 */\n.pet-tarot-stage{position:relative!important;overflow:hidden!important;background:radial-gradient(circle at 50% 0%,rgba(223,207,155,.16),transparent 34%),linear-gradient(180deg,#fff 0%,#fbfcfa 100%)!important}.pet-tarot-stage:before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 18% 12%,rgba(79,138,91,.06),transparent 22%),radial-gradient(circle at 82% 22%,rgba(211,181,105,.07),transparent 20%)}\n.pet-tarot-shuffle-stack{filter:drop-shadow(0 18px 28px rgba(24,45,35,.18))}.pet-tarot-shuffle-stack i{border:1px solid rgba(224,198,124,.88)!important;background:linear-gradient(145deg,#1c3a2f 0%,#244c3b 54%,#142d25 100%)!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.05),0 12px 28px rgba(25,48,38,.15)!important;animation-duration:.92s!important}.pet-tarot-shuffle-stack i:after{content:"";position:absolute;inset:8px;border:1px solid rgba(239,216,155,.26);border-radius:13px;pointer-events:none}\n.pet-tarot-deck22{perspective:1000px!important}.pet-tarot-back22{border-color:#d8c58b!important;background:linear-gradient(155deg,#19382d,#28513f)!important;box-shadow:0 9px 18px rgba(28,52,40,.13)!important;will-change:transform;transition:transform .34s cubic-bezier(.2,.85,.2,1),filter .3s ease,opacity .25s ease!important;animation:tarotDealV6 .42s cubic-bezier(.2,.8,.2,1) both;animation-delay:var(--delay)!important}.pet-tarot-back22:hover{transform:translateY(-18px) scale(1.045) rotate(var(--r))!important;filter:brightness(1.04) drop-shadow(0 14px 18px rgba(31,56,44,.2))!important}.pet-tarot-back22.picked{transform:translateY(-54px) scale(1.12) rotate(0deg)!important;filter:drop-shadow(0 22px 25px rgba(28,54,41,.25))!important}@keyframes tarotDealV6{from{opacity:0;transform:translateY(20px) scale(.94) rotate(0)}to{opacity:1;transform:translateY(var(--lift)) rotate(var(--r))}}\n.pet-tarot-reveal-scene{position:relative}.pet-tarot-reveal-scene:before{content:"";position:absolute;width:300px;height:300px;border-radius:50%;background:radial-gradient(circle,rgba(226,199,120,.18),rgba(226,199,120,0) 66%);animation:tarotGlowV6 1.15s ease both}@keyframes tarotGlowV6{from{opacity:0;transform:scale(.68)}55%{opacity:1}to{opacity:.55;transform:scale(1.12)}}.pet-tarot-reveal-card{z-index:1;animation:tarotLiftV6 .62s cubic-bezier(.2,.9,.2,1) both!important}.pet-tarot-reveal-inner{animation:tarotFlipV6 1.02s cubic-bezier(.18,.78,.22,1) .12s both!important}.pet-tarot-reveal-front{background:linear-gradient(155deg,#fffdf7 0%,#f8f1df 56%,#eee0b9 100%)!important;border:1px solid #cfb56d!important;box-shadow:inset 0 0 0 7px rgba(255,255,255,.55)!important}@keyframes tarotLiftV6{from{opacity:0;transform:translateY(44px) scale(.84)}to{opacity:1;transform:none}}@keyframes tarotFlipV6{0%{transform:rotateY(0) scale(.98)}45%{transform:rotateY(88deg) scale(1.035)}100%{transform:rotateY(180deg) scale(1)}}\n.pet-tarot-result-topic{padding:11px 14px!important;border:1px solid #e6e6dc!important;border-radius:14px!important;background:rgba(255,255,255,.8)!important;box-shadow:0 8px 24px rgba(43,64,50,.05)!important}.pet-tarot-result-wrap{padding:22px!important;border:1px solid #e2e8e2!important;border-radius:26px!important;background:linear-gradient(145deg,rgba(255,255,255,.96),rgba(247,250,247,.96))!important;box-shadow:0 20px 50px rgba(39,61,47,.08)!important}.pet-tarot-face{position:relative!important;border-radius:24px!important;overflow:hidden!important;border:1px solid #cfb56d!important;background:linear-gradient(155deg,#fffdf7,#f3e6c4)!important;box-shadow:0 18px 36px rgba(42,57,46,.14),inset 0 0 0 7px rgba(255,255,255,.55)!important}.pet-tarot-face:after{content:"";position:absolute;inset:10px;border:1px solid rgba(138,110,48,.28);border-radius:17px;pointer-events:none}.pet-tarot-number{letter-spacing:.16em!important;color:#8b7440!important}.pet-tarot-art span{filter:drop-shadow(0 10px 18px rgba(74,59,29,.12))!important}.pet-tarot-title b{font-size:21px!important;letter-spacing:-.025em!important}.pet-tarot-reading{background:linear-gradient(180deg,#fff,#fafcf9)!important;border:1px solid #dfe7e1!important;border-radius:22px!important;box-shadow:0 9px 24px rgba(47,69,54,.055)!important}.pet-tarot-reading>.bg-chip{background:#234a39!important;color:#fff!important;border-color:#234a39!important;box-shadow:none!important}.pet-tarot-reading h3{color:#2d4938!important;letter-spacing:-.02em!important}.pet-tarot-luck{border:1px solid #ead9a9!important;background:linear-gradient(135deg,#fffaf0,#fff6dc)!important;color:#68552b!important}.pet-tarot-actions .bg-btn{min-height:48px!important;border-radius:14px!important;background:linear-gradient(135deg,#315f47,#234c39)!important;box-shadow:0 8px 18px rgba(40,78,57,.18)!important}.pet-tarot-once-note{font-size:11px!important;color:#7e897f!important;text-align:center!important;margin-top:13px!important}\n@media(max-width:680px){.pet-tarot-result-wrap{padding:15px!important;border-radius:20px!important}.pet-tarot-face{max-width:205px!important}.pet-tarot-back22:hover{transform:translateY(var(--lift)) rotate(var(--r))!important}}\n'''
if 'PET_TAROT_PREMIUM_V6' not in t:
    t=t.replace(marker,premium+'\n'+marker,1)
tar.write_text(t,encoding='utf-8')
print('PetGrow polish patch applied')
